// Junta todos os IDs de mensagens com anexo (todas as páginas) em um único item
const ids = [];
for (const item of $input.all()) {
  for (const m of (item.json.messages || [])) ids.push(m.id);
}
return [{ json: { attachmentIds: ids, total: ids.length } }];

// Normaliza os metadados de cada e-mail. Somente leitura: nada é alterado no Gmail.
const labelsResp = $('Listar labels').first().json.labels || [];
const labelMap = Object.fromEntries(labelsResp.map(l => [l.id, l.name]));
const attachmentIds = new Set($('Juntar IDs com anexo').first().json.attachmentIds || []);
const cfg = $('Config').first().json;
const bigBytes = cfg.bigSizeMB * 1024 * 1024;
const oldMs = cfg.oldYears * 365.25 * 24 * 3600 * 1000;
const agora = Date.now();

const header = (headers, name) => {
  const h = headers.find(x => (x.name || '').toLowerCase() === name.toLowerCase());
  return h ? h.value : '';
};
const parseFrom = (from) => {
  const m = from.match(/^(.*?)\s*<([^>]+)>\s*$/);
  const email = (m ? m[2] : from).trim().toLowerCase();
  const nome = (m ? m[1] : '').replace(/^"|"$/g, '').trim();
  return { nome, email };
};
// Mascara sequências de 6 a 8 dígitos (códigos de verificação) antes de gravar na planilha
const mascarar = (s) => String(s || '').replace(/\b\d{6,8}\b/g, '••••••');

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.id || j.error) continue;
  const headers = (j.payload && j.payload.headers) || [];
  const { nome, email } = parseFrom(header(headers, 'From'));
  const dominio = email.includes('@') ? email.split('@')[1] : '';
  const ts = Number(j.internalDate);
  const data = new Date(ts);
  const labelIds = j.labelIds || [];
  const labelsUsuario = labelIds.filter(id => id.startsWith('Label_')).map(id => labelMap[id] || id);
  const categoriaGmail = (labelIds.find(id => id.startsWith('CATEGORY_')) || '').replace('CATEGORY_', '');
  const listUnsub = header(headers, 'List-Unsubscribe');
  const listId = header(headers, 'List-Id');
  const precedence = header(headers, 'Precedence').toLowerCase();
  const autoSub = header(headers, 'Auto-Submitted').toLowerCase();
  const isNewsletter = !!(listUnsub || listId) || precedence === 'bulk' || precedence === 'list';
  const isNoReply = /no-?reply|notifica|notification|alert|mailer-daemon|bounce/.test(email);
  const temAnexo = attachmentIds.has(j.id);

  out.push({ json: {
    messageId: j.id,
    threadId: j.threadId,
    data: data.toISOString(),
    ano: data.getFullYear(),
    remetenteNome: nome,
    remetenteEmail: email,
    dominio,
    destinatario: header(headers, 'To').slice(0, 200),
    assunto: mascarar(header(headers, 'Subject')).slice(0, 300),
    trecho: mascarar(j.snippet).slice(0, 200),
    labels: labelIds.map(id => labelMap[id] || id).join(', '),
    labelsUsuario: labelsUsuario.join(', '),
    semLabelUsuario: labelsUsuario.length === 0,
    categoriaGmail,
    naInbox: labelIds.includes('INBOX'),
    naoLido: labelIds.includes('UNREAD'),
    temAnexo,
    tamanhoMB: Math.round(((j.sizeEstimate || 0) / 1048576) * 100) / 100,
    anexoGrande: temAnexo && (j.sizeEstimate || 0) >= bigBytes,
    isNewsletter,
    isAutomatico: isNoReply || (!!autoSub && autoSub !== 'no'),
    temListUnsubscribe: !!listUnsub,
    antigo: (agora - ts) > oldMs,
    linkGmail: `https://mail.google.com/mail/u/0/#all/${j.threadId}`,
    coletadoEm: new Date().toISOString(),
  }});
}
return out;

// Gera as tabelas do relatório de diagnóstico (uma linha por item, agrupadas por seção)
const rows = $input.all().map(i => i.json);
const geradoEm = new Date().toISOString();
const out = [];
const add = (secao, item, quantidade, detalhe = '') =>
  out.push({ json: { geradoEm, secao, item: String(item), quantidade, detalhe } });

const contar = (lista, chaveFn) => {
  const m = new Map();
  for (const r of lista) {
    for (const k of [].concat(chaveFn(r))) {
      if (k === undefined || k === null || k === '') continue;
      m.set(k, (m.get(k) || 0) + 1);
    }
  }
  return [...m.entries()].sort((a, b) => b[1] - a[1]);
};
const total = rows.length;
const pct = n => total ? ((n / total) * 100).toFixed(1) + '%' : '0%';
const nomes = {};
for (const r of rows) if (r.remetenteNome && !nomes[r.remetenteEmail]) nomes[r.remetenteEmail] = r.remetenteNome;

const resumo = {
  'Total analisado': total,
  'Na caixa de entrada': rows.filter(r => r.naInbox).length,
  'Arquivados (fora da inbox)': rows.filter(r => !r.naInbox).length,
  'Não lidos': rows.filter(r => r.naoLido).length,
  'Sem label do usuário': rows.filter(r => r.semLabelUsuario).length,
  'Newsletters / listas': rows.filter(r => r.isNewsletter).length,
  'Notificações automáticas': rows.filter(r => r.isAutomatico && !r.isNewsletter).length,
  'Com anexo': rows.filter(r => r.temAnexo).length,
  'Com anexo grande': rows.filter(r => r.anexoGrande).length,
  'Antigos': rows.filter(r => r.antigo).length,
};
// Cobertura: quantos e-mails a busca encontrou, quantos o limite cortou e quantas leituras falharam.
// Sem isso, falhas de leitura somem em silêncio e o relatório parece completo sem ser.
const encontrados = $('Separar mensagens').all().length;
const dentroDoLimite = $('Limitar lote').all().length;
const falhas = $('Buscar metadados').all().filter(i => !i.json.id || i.json.error).length;
add('COBERTURA', 'Encontrados na busca', encontrados);
add('COBERTURA', 'Fora do limite maxEmails', encontrados - dentroDoLimite, encontrados > dentroDoLimite ? 'aumente maxEmails no Config' : '');
add('COBERTURA', 'Falhas de leitura', falhas, falhas ? 'não entram no relatório; rode de novo' : '');
add('COBERTURA', 'Analisados', total, encontrados ? ((total / encontrados) * 100).toFixed(1) + '% do encontrado' : '');

for (const [k, v] of Object.entries(resumo)) add('RESUMO', k, v, pct(v));

for (const [k, v] of contar(rows, r => r.remetenteEmail).slice(0, 30)) add('TOP_REMETENTES', k, v, nomes[k] || '');
for (const [k, v] of contar(rows, r => r.dominio).slice(0, 30)) add('TOP_DOMINIOS', k, v, pct(v));
for (const [k, v] of contar(rows, r => r.ano).sort((a, b) => b[0] - a[0])) add('POR_ANO', k, v, pct(v));
for (const [k, v] of contar(rows, r => r.labels ? r.labels.split(', ') : [])) add('POR_LABEL', k, v, pct(v));
for (const [k, v] of contar(rows, r => r.categoriaGmail || 'SEM_CATEGORIA')) add('POR_CATEGORIA_GMAIL', k, v, pct(v));

const news = rows.filter(r => r.isNewsletter);
for (const [k, v] of contar(news, r => r.remetenteEmail).slice(0, 25)) {
  const naoLidos = news.filter(r => r.remetenteEmail === k && r.naoLido).length;
  add('TOP_NEWSLETTERS', k, v, `${nomes[k] || ''} | não lidos: ${naoLidos}`);
}
const notif = rows.filter(r => r.isAutomatico && !r.isNewsletter);
for (const [k, v] of contar(notif, r => r.remetenteEmail).slice(0, 25)) add('TOP_NOTIFICACOES', k, v, nomes[k] || '');

const antigos = rows.filter(r => r.antigo);
for (const [k, v] of contar(antigos, r => r.remetenteEmail).slice(0, 20)) add('ANTIGOS_POR_REMETENTE', k, v, nomes[k] || '');

rows.filter(r => r.anexoGrande)
  .sort((a, b) => b.tamanhoMB - a.tamanhoMB)
  .slice(0, 30)
  .forEach(r => add('ANEXOS_GRANDES', r.remetenteEmail, r.tamanhoMB, `${r.data.slice(0, 10)} | ${r.assunto}`));

return out;

// Monta o relatório em HTML para e-mail. Clientes de e-mail ignoram CSS externo e <style>,
// então todo o visual usa estilos inline e tabelas.
const itens = $input.all().map(i => i.json);
const titulos = {
  COBERTURA: 'Cobertura da leitura', RESUMO: 'Resumo', TOP_REMETENTES: 'Top 30 remetentes', TOP_DOMINIOS: 'Top domínios',
  POR_ANO: 'E-mails por ano', POR_LABEL: 'E-mails por label', POR_CATEGORIA_GMAIL: 'Categorias do Gmail',
  TOP_NEWSLETTERS: 'Principais newsletters', TOP_NOTIFICACOES: 'Principais notificações',
  ANTIGOS_POR_REMETENTE: 'E-mails antigos por remetente', ANEXOS_GRANDES: 'Anexos grandes (MB)',
};
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const secoes = {};
for (const i of itens) (secoes[i.secao] ||= []).push(i);
const valor = (sec, item) => ((secoes[sec] || []).find(i => i.item === item) || {}).quantidade ?? 0;
const num = n => typeof n === 'number' ? n.toLocaleString('pt-BR') : esc(n);

const cor = { texto: '#1f2937', suave: '#6b7280', borda: '#e5e7eb', fundo: '#f3f4f6', zebra: '#f9fafb', destaque: '#2563eb', alerta: '#b00020' };
const fonte = 'font-family:Arial,Helvetica,sans-serif';
const quando = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const incompleto = itens.some(i => i.secao === 'COBERTURA' && /^(Fora do limite|Falhas)/.test(i.item) && i.quantidade > 0);

// Cartões com os números principais
const cartoes = [
  ['Analisados', valor('RESUMO', 'Total analisado')],
  ['Não lidos', valor('RESUMO', 'Não lidos')],
  ['Sem marcador', valor('RESUMO', 'Sem label do usuário')],
  ['Newsletters', valor('RESUMO', 'Newsletters / listas')],
].map(([rotulo, n]) => `<td width="25%" style="padding:4px">`
  + `<div style="background:#ffffff;border:1px solid ${cor.borda};border-radius:8px;padding:12px 6px;text-align:center">`
  + `<div style="font-size:22px;font-weight:bold;color:${cor.texto}">${num(n)}</div>`
  + `<div style="font-size:12px;color:${cor.suave};margin-top:2px">${rotulo}</div></div></td>`).join('');

// Detalhes no formato "30.5%" ganham uma barra proporcional
const barra = detalhe => {
  const m = /^(\d+(?:\.\d+)?)%$/.exec(String(detalhe));
  if (!m) return esc(detalhe);
  const p = Math.min(Number(m[1]), 100);
  return `<div style="font-size:11px;color:${cor.suave}">${esc(detalhe)}</div>`
    + `<div style="background:${cor.fundo};border-radius:3px;height:6px;margin-top:3px">`
    + `<div style="background:${cor.destaque};border-radius:3px;height:6px;width:${p}%"></div></div>`;
};

const tabela = (sec, lista) => `<h3 style="${fonte};font-size:15px;color:${cor.texto};margin:24px 0 8px">${esc(titulos[sec] || sec)}</h3>`
  + `<table width="100%" cellpadding="0" cellspacing="0" style="${fonte};font-size:13px;border-collapse:collapse;border:1px solid ${cor.borda}">`
  + `<tr style="background:${cor.fundo};color:${cor.suave};font-size:11px;text-transform:uppercase">`
  + `<th align="left" style="padding:8px">Item</th><th align="right" style="padding:8px">Qtd</th><th align="left" style="padding:8px;width:35%">Detalhe</th></tr>`
  + lista.map((i, n) => `<tr style="background:${n % 2 ? cor.zebra : '#ffffff'};border-top:1px solid ${cor.borda}">`
    + `<td style="padding:7px 8px;color:${cor.texto};word-break:break-all">${esc(i.item)}</td>`
    + `<td align="right" style="padding:7px 8px;color:${cor.texto};font-weight:bold;white-space:nowrap">${num(i.quantidade)}</td>`
    + `<td style="padding:7px 8px;color:${cor.suave}">${barra(i.detalhe)}</td></tr>`).join('')
  + `</table>`;

let html = `<div style="background:${cor.fundo};padding:16px 0">`
  + `<table align="center" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border-radius:10px;${fonte}">`
  + `<tr><td style="background:${cor.destaque};border-radius:10px 10px 0 0;padding:20px 24px;color:#ffffff">`
  + `<div style="font-size:20px;font-weight:bold">📬 Diagnóstico do Gmail</div>`
  + `<div style="font-size:13px;opacity:0.9;margin-top:4px">Gerado em ${quando} · somente leitura, nenhuma alteração na caixa</div></td></tr>`
  + `<tr><td style="padding:16px 20px 24px">`;
if (incompleto) {
  html += `<div style="background:#fdecee;border-left:4px solid ${cor.alerta};padding:10px 12px;color:${cor.alerta};font-size:13px;margin-bottom:12px">`
    + `<b>Atenção:</b> relatório parcial. Veja a seção Cobertura da leitura.</div>`;
}
html += `<table width="100%" cellpadding="0" cellspacing="0"><tr>${cartoes}</tr></table>`;
for (const [sec, lista] of Object.entries(secoes)) html += tabela(sec, lista);
html += `</td></tr>`
  + `<tr><td style="padding:12px 24px;border-top:1px solid ${cor.borda};font-size:11px;color:${cor.suave}">`
  + `gmail-organizer-n8n · Fase 1 (diagnóstico)</td></tr></table></div>`;

return [{ json: { html, assunto: `[Gmail] Diagnóstico – ${new Date().toISOString().slice(0, 10)}` } }];

// Monta a mensagem MIME (RFC 2822) e codifica em base64url, formato exigido pela Gmail API
const to = $('Obter meu e-mail').first().json.emailAddress;
const { html, assunto } = $('Montar e-mail').first().json;
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const mime = [
  `To: ${to}`,
  `From: ${to}`,
  `Subject: =?UTF-8?B?${b64(assunto)}?=`,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(html).replace(/.{76}/g, '$&\r\n'),
].join('\r\n');
const raw = b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { para: to, raw } }];
